SELECT json_build_object(
 'database',current_database(),'version',version(),'socket',inet_server_addr() IS NULL,
 'captured_at',clock_timestamp(),'source_baseline','9e08dca302621f45eb5b377a43bda21eeb1951e1 + Task25 candidate syntax correction',
 'policies',(SELECT json_agg(p ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('viewings','listings')),
 'tables',(SELECT json_agg(json_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl,'columns',(SELECT json_agg(json_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'acl',a.attacl,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT json_agg(pg_get_constraintdef(x.oid,true)) FROM pg_constraint x WHERE x.conrelid=c.oid))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('viewings','listings')),
 'triggers',(SELECT json_agg(json_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true),'function',t.tgfoid::regprocedure::text)) FROM pg_trigger t WHERE t.tgrelid IN ('public.viewings'::regclass,'public.leads'::regclass,'public.notifications'::regclass) AND NOT t.tgisinternal),
 'routines',(SELECT json_agg(json_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'name',p.proname,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig,'body',p.prosrc,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname IN ('public','private') AND p.proname IN ('can_request_viewing_for_listing','has_org_permission','get_listing_reference_catalogue','authoritative_role','get_viewing_limit','is_pro','has_platform_admin','has_current_billing_subscription_for_user','current_billing_subscription_for_user','has_investor_subscription_for_user','current_billing_runtime_mode','profile_pricing_audience','check_viewing_limit','capture_viewing_owner_lead','notify_viewing_created','notify_viewing_status_changed','insert_interaction_notification','upsert_owner_lead','guard_viewing_status_transitions','set_lead_origin_context_key','update_updated_at_column')) OR (n.nspname='auth' AND p.proname IN ('uid','role'))),
 'access',json_build_object('viewing_insert',has_table_privilege('authenticated','public.viewings','INSERT'),'viewing_select',has_table_privilege('authenticated','public.viewings','SELECT'),'listing_id_select',has_column_privilege('authenticated','public.listings','id','SELECT'),'listing_owner_select',has_column_privilege('authenticated','public.listings','owner_id','SELECT'))
);
